import sys

def solve():
    T = int(sys.stdin.readline())
    for _ in range(T):
        S = sys.stdin.readline().strip()
        n = len(S)
        max_len = -1
        # Precompute all prefixes and suffixes of S
        prefixes = set()
        suffixes = set()
        for i in range(1, n+1):
            prefixes.add(S[:i])
            suffixes.add(S[-i:])
        # Check all possible substrings of S in descending order of length
        found = False
        for l in range(n, 0, -1):
            for i in range(n - l + 1):
                P = S[i:i+l]
                valid = True
                # Check no non-empty substring of P is a prefix of S
                for k in range(1, l+1):
                    if P[:k] in prefixes:
                        valid = False
                        break
                if not valid:
                    continue
                # Check no non-empty substring of P is a suffix of S
                for k in range(1, l+1):
                    if P[-k:] in suffixes:
                        valid = False
                        break
                if valid:
                    max_len = l
                    found = True
                    break
            if found:
                break
        print(max_len)

solve()
